import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"便签与收藏","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/clips-favorites.md","filePath":"guide/misskey/clips-favorites.md","lastUpdated":1789295632000}'),r={name:"guide/misskey/clips-favorites.md"};function s(o,a,n,d,c,p){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="便签与收藏" tabindex="-1">便签与收藏 <a class="header-anchor" href="#便签与收藏" aria-label="Permalink to &quot;便签与收藏&quot;">​</a></h1><p>便签和收藏都是「保存帖子」的工具，区别在于可见性。</p><h2 id="便签" tabindex="-1">便签 <a class="header-anchor" href="#便签" aria-label="Permalink to &quot;便签&quot;">​</a></h2><p>便签（Clip）是自建的帖子合集，可以把帖子归类收藏：</p><ul><li>通过侧栏「便签」创建合集，例如「同人图存档」「灵感记录」。</li><li>在任意帖子的菜单中选择「添加到便签」即可收藏进合集。</li><li>便签可以设置为<strong>公开</strong>并分享链接，其他人可以浏览你的合集；也可保持私有。</li><li>可以给便签填写名称、描述。</li></ul><h2 id="收藏" tabindex="-1">收藏 <a class="header-anchor" href="#收藏" aria-label="Permalink to &quot;收藏&quot;">​</a></h2><p>收藏（Favorites）是更轻量的单层收藏夹：</p><ul><li>在帖子菜单中选择「收藏」，帖子会进入「我的收藏」。</li><li>收藏列表仅自己可见，适合随手标记想以后再看的帖子。</li><li>在帖子菜单中可随时取消收藏。</li></ul><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><ul><li>只是随手 mark 一下 → 收藏。</li><li>想按主题长期整理、或展示给他人看 → 便签。</li></ul>',10)])])}const _=e(r,[["render",s]]);export{u as __pageData,_ as default};
